/*
 * Strictly server-derived responses for common customer service questions.
 * Gemini determines intent for free-form messages; prices, VAT, discounts and
 * logistics are NEVER generated by the model.
 */
import {productFor,resolveProduct} from './catalogue.mjs';

const normalise = v => String(v||'')
  .normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d')
  .toLowerCase().replace(/\s+/g,' ').trim();
const money = n => Math.round(n).toLocaleString('vi-VN')+' đ';
const containsOrder = s => /\b(?:cho|dat|mua|lay|gui|ship|them|order)\s+(?:toi|anh|chi|em|minh|giup|dum)?\s*\d+\s*(?:thung|chai|binh|loc|t|nuoc|suoi|satori|hikari|premium|500|350|5l)/.test(s);
const isQuestion = s => /\b(?:bao nhieu|gia|chi phi|co khong|duoc khong|the nao|may|thu|tinh|sao|phi|thue|vat|giam gia|chiet khau)\b/.test(s) || s.includes('?');

/** Only return facts from the customer's approved sandbox profile and catalogue. */
export function businessReply(message,profile={}) {
 const s=normalise(message);
 if(!s||s.length>500) return null;
 if(containsOrder(s) || /\b(?:doi dia chi|nguoi nhan khac|doi so dien thoai|doi sdt|them vao don|them thung nua)\b/.test(s))
  return null; // order, modification and identity checks belong to transaction guardrails

 if(/\b(?:xin chao|chao shop|hello|hi shop|alo shop)\b/.test(s) && s.length<45)
  return {kind:'greeting',message:'Xin chào! Mình hỗ trợ chọn nước Satori, Hikari và Juice, kiểm tra giá riêng, tạo giỏ hàng, hóa đơn TEST và yêu cầu giao hàng. Bạn muốn xem sản phẩm nào?'};

 if(/\b(?:da thanh toan|chua thanh toan|cong no|lich su(?: don| hoa don)?|don cua toi|hoa don cua toi|kiem tra don|trang thai don)\b/.test(s))
  return {kind:'order_status',message:'Bạn mở mục Lịch sử & Excel để xem các hóa đơn TEST thuộc đúng link của mình, số tiền và trạng thái đã lưu. Nếu có vướng mắc thanh toán hoặc đơn thực tế, cửa hàng phải xác minh; AI không tự đánh dấu đã trả tiền.'};

 if(/\b(?:chiet khau|giam gia|uu dai|gia rieng|ck\s*%)\b/.test(s) && isQuestion(s))
  return {kind:'discount',message:'Link khách TEST này hiện được cấu hình chiết khấu '+Number(profile.discount||0)+'% trên giá niêm yết. Giá từng mặt hàng sau chiết khấu được tính trên máy chủ; chọn Tất cả sản phẩm để xem.'};

 if(/\b(?:vat|thue)\b/.test(s) && isQuestion(s))
  return {kind:'vat',message:'Thuế VAT cấu hình cho link TEST này là '+Number(profile.vatRate??0)+'%. Báo giá và hóa đơn hiển thị riêng tiền hàng, phí giao và VAT trước khi bạn xác nhận.'};

 if(/\b(?:phi ship|phi giao|phi van chuyen|giao hang mat phi|ship bao nhieu|phi ship bao nhieu)\b/.test(s))
  return {kind:'shipping',message:'Phí giao hàng của link TEST này được cấu hình '+Number(profile.ship||0)+'% trên tiền hàng sau chiết khấu. Số tiền cụ thể được server tính trên báo giá; thời gian giao cần cửa hàng xác nhận.'};

 if(/\b(?:bao lau|may ngay|bao gio|khi nao giao|giao duoc khong|bao nhieu gio|thoi gian giao)\b/.test(s) && /\b(?:giao|ship|van chuyen)\b/.test(s))
  return {kind:'delivery',message:'Bạn có thể ghi giờ giao mong muốn trong yêu cầu đặt hàng. Đây là yêu cầu, chưa phải cam kết; cửa hàng cần xác nhận lịch và khả năng giao thực tế.'};

 if(/\b(?:gia|bao nhieu tien|bao gia|don gia|gia niem yet|gia bao nhieu|tien mot)\b/.test(s) && isQuestion(s)){
   const selection=resolveProduct(s,profile);
   const product=selection.sku&&!selection.ambiguous?productFor(selection.sku):null;
   if(!product)
     return {kind:'price_clarify',message:'Bạn muốn hỏi giá loại nước nào? Có thể chọn Satori 350ml, 500ml, Premium, 5L hoặc mở Tất cả sản phẩm để xem mã và đơn vị rõ ràng.'};
   const unitPrice=Math.round(product.listPrice*(1-Number(profile.discount||0)/100));
   return {kind:'price',message:product.name+' • '+product.spec+'. Giá niêm yết '+money(product.listPrice)+' / '+product.unit+'; giá theo link TEST sau chiết khấu '+Number(profile.discount||0)+'% là '+money(unitPrice)+' / '+product.unit+'. Chưa gồm phí giao và VAT; chọn số lượng để hệ thống lập báo giá tổng.'};
 }
 return null;
}
